export default function App() {
  const [glassesFile, setGlassesFile] = useState<File | null>(null);
  const [glassesPreview, setGlassesPreview] = useState<string | null>(null);
  const [attributes, setAttributes] = useState<ModelAttributes>(INITIAL_ATTRIBUTES);
  const [state, setState] = useState<GenerationState>({
    isLoading: false,
    resultImages: [],
    error: null,
  });
  const [editPrompt, setEditPrompt] = useState<string>('');
  const [selectedImageIndex, setSelectedImageIndex] = useState<number>(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setGlassesFile(file);
      setGlassesPreview(URL.createObjectURL(file));
      setState(prev => ({ ...prev, resultImages: [], error: null }));
    }
  };

  const handleAttributeChange = (key: keyof ModelAttributes, value: string) => {
    setAttributes(prev => ({ ...prev, [key]: value }));
  };

  const handleGenerate = async () => {
    if (!glassesFile) {
      setState(prev => ({ ...prev, error: "Please upload an image of the eyeglasses first." }));
      return;
    }

    setState({ isLoading: true, resultImages: [], error: null });

    try {
      // Generate two variations in parallel
      const results = await Promise.all([
        generateModelWithGlasses(glassesFile, attributes),
        generateModelWithGlasses(glassesFile, attributes)
      ]);
      setState({ isLoading: false, resultImages: results, error: null });
      setSelectedImageIndex(0);
      setEditPrompt('');
    } catch (err: any) {
      setState({ isLoading: false, resultImages: [], error: err.message || "Something went wrong." });
    }
  };

  const handleEdit = async () => {
    if (state.resultImages.length === 0 || !editPrompt.trim()) return;

    const currentImage = state.resultImages[selectedImageIndex];
    setState(prev => ({ ...prev, isLoading: true, error: null }));

    try {
      const result = await editGeneratedImage(currentImage, editPrompt);
      const newImages = [...state.resultImages];
      newImages[selectedImageIndex] = result;
      setState({ isLoading: false, resultImages: newImages, error: null });
      setEditPrompt('');
