import { GoogleGenAI } from "@google/genai";
import { ModelAttributes } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Converts a File object to a Base64 string.
 */
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Generates an image using Gemini 2.5 Flash Image.
 * It combines the uploaded glasses image with a prompt describing the model.
 */
export const generateModelWithGlasses = async (
  glassesFile: File,
  attributes: ModelAttributes
): Promise<string> => {
  try {
    const imagePart = await fileToGenerativePart(glassesFile);

    // Map Environment options to specific prompts
    const environmentPrompts: Record<string, { setting: string; background: string }> = {
      "Clean Spacious Room": {
        setting: "spacious and minimalist white room",
        background: "The distant walls of the room are visible, creating a sense of depth. The background is simple and uncluttered, with sunlight and shadow patterns."
      },
      "Modern Office": {
        setting: "sleek modern office with glass elements",
        background: "Blurred office background with glass partitions, contemporary furniture, and cool ambient lighting."
      },
      "South East Asian Park": {
        setting: "lush tropical park in Southeast Asia",
        background: "Vibrant tropical greenery, palm trees, and dappled sunlight filtering through the canopy."
      },
      "Urban Walking Path (SEA)": {
        setting: "clean urban walking path in a Southeast Asian city",
        background: "Textured pavement, manicured city greenery, and blurred modern city architecture in the distance."
      },
      "Midday Coffee Shop": {
        setting: "stylish coffee shop with natural light",
        background: "Interior of a cafe with large windows, warm tones, and bright natural light streaming in."
      }
    };

    const env = environmentPrompts[attributes.environment] || environmentPrompts["Clean Spacious Room"];

    // Map Color Grading options
    const colorGradingPrompts: Record<string, string> = {
      "Film Simulation": "mimicking the specific color palette of the attached reference image, with slightly adjusted contrast, deepened shadows, and carefully controlled highlights. Visible film grain.",
      "Magazine": "High contrast, vibrant colors, sharp details, glossy magazine editorial look, slightly saturated, pristine lighting.",
