export const generateModelWithGlasses = async (
  glassesFile: File,
  fashionFile: File | null,
  attributes: ModelAttributes,
  specificSeed: number
): Promise<{ imageUrl: string; promptJson: string }> => {
  try {
    const glassesPart = await fileToGenerativePart(glassesFile);
    const parts: any[] = [glassesPart];

    let fashionPart = null;
    if (fashionFile) {
      fashionPart = await fileToGenerativePart(fashionFile);
      parts.push(fashionPart);
    }

    const expressionPrompts: Record<string, string> = {
      "Gazing left/right with slightly smile": "Head turned slightly side, looking off-camera, gentle smile.",
