      ${fashionFile ? "2. Model MUST wear the outfit from the second image." : ""}
      3. Style guidelines: ${JSON.stringify(jsonPrompt)}
      NEGATIVE: western features, caucasian, european face, looking at camera.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [...parts, { text: textPrompt }] },
      config: {
        imageConfig: { 
          aspectRatio: attributes.aspectRatio === "3:4" ? "3:4" : "4:3",
          seed: specificSeed
        }
      }
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
