  gender: string;
  age: string;
  ethnicity: string;
  hairStyle: string;
  hairColor: string;
  clothing: string;
  environment: string;
  lighting: string;
  artStyle: string;
  colorGrading: string;
  aspectRatio: string;
  skinTexture: string;
  facialExpression: string;
  seed: number;
  pose: string;
  shotType: string;
  handProps: string;
