import { GoogleGenAI } from "@google/genai";
import { ModelAttributes } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const generateModelWithGlasses = async (
  glassesFile: File,
  fashionFile: File | null,
  envFile: File | null,
  handPropsFile: File | null,
  attributes: ModelAttributes,
  specificSeed: number
): Promise<{ imageUrl: string; promptJson: string }> => {
  try {
    const glassesPart = await fileToGenerativePart(glassesFile);
    const parts: any[] = [glassesPart];

    if (fashionFile) {
      const fashionPart = await fileToGenerativePart(fashionFile);
      parts.push(fashionPart);
    }

    if (envFile && attributes.environment === "Reference upload (default)") {
      const envRefPart = await fileToGenerativePart(envFile);
      parts.push(envRefPart);
    }

    if (handPropsFile && attributes.handProps === "reference upload (default)") {
      const handRefPart = await fileToGenerativePart(handPropsFile);
      parts.push(handRefPart);
    }

    const colorGradingPrompts: Record<string, string> = {
      "Film Simulation": "Analog film aesthetic, subtle grain, natural skin tones, soft shadows.",
      "Magazine": "High-fashion magazine editorial look. Natural contrast, slight saturation, sharp focus, vibrant and clean colors.",
      "Web Use": "E-commerce standard. Middle tone focus with natural color feel, accurate and realistic color representation."
    };

    const environmentPrompts: Record<string, string> = {
      "Reference upload (default)": "Environment from the uploaded reference image.",
      "Clean Spacious Room": "Inside a clean, minimalist white room with soft shadows.",
      "Modern Office": "Sleek contemporary office interior with blurred workstations and architectural glass.",
      "South East Asian Park": "Tropical lush park in Southeast Asia, vibrant greenery and dappled sunlight.",
      "Urban Walking Path (SEA)": "Modern urban pedestrian walkway in a Southeast Asian city, architectural elements in distance.",
      "Midday Coffee Shop": "Stylish coffee shop interior with natural midday light streaming through large windows."
    };

    const isSEAsian = attributes.ethnicity.toLowerCase().includes("south east") || 
                      attributes.ethnicity.toLowerCase().includes("thailand") || 
                      attributes.ethnicity.toLowerCase().includes("singapore") ||
                      attributes.ethnicity.toLowerCase().includes("vietnam");

    const jsonPrompt = {
      subject: `A ${attributes.ethnicity} ${attributes.gender} model, age ${attributes.age}.`,
      eyewear: "Model is wearing the exact eyeglasses shown in the primary reference image.",
      clothing: (fashionFile && attributes.clothing.includes("1"))
        ? "Model is wearing the outfit shown in the fashion flat-lay reference image." 
        : attributes.clothing,
      features: isSEAsian ? "Authentic Southeast Asian facial features, distinct eye shape." : "Natural features.",
      skin: attributes.skinTexture,
      expression: attributes.facialExpression,
      environment: environmentPrompts[attributes.environment] || attributes.environment,
      hand_props: (handPropsFile && attributes.handProps.includes("reference"))
        ? "Model is holding the item shown in the hand props reference image."
        : `Model is holding a ${attributes.handProps}.`,
      composition: {
        pose: `The model is ${attributes.pose}.`,
        shot_type: attributes.shotType,
      },
      photography: {
        style: attributes.artStyle,
        lighting: attributes.lighting,
        color_grading: colorGradingPrompts[attributes.colorGrading] || attributes.colorGrading,
        skin_detail: attributes.skinTexture,
        negative_aspect: "looking directly to camera"
      }
    };

    const textPrompt = `
      Create a photorealistic portrait.
      1. Model MUST wear the eyeglasses from the first image.
      ${fashionFile ? "2. Model wears the outfit from the clothing reference image." : ""}
      ${envFile ? "3. Model is placed in the environment shown in the environment reference image." : ""}
      ${handPropsFile ? "4. Model is holding the prop from the hand props reference image." : ""}
      5. Style guidelines: ${JSON.stringify(jsonPrompt)}
      NEGATIVE: looking directly to camera, western features, caucasian, european face.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [...parts, { text: textPrompt }] },
      config: {
        imageConfig: { 
          aspectRatio: attributes.aspectRatio,
          seed: specificSeed
        }
      }
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return { 
            imageUrl: `data:image/png;base64,${part.inlineData.data}`,
            promptJson: JSON.stringify(jsonPrompt, null, 2)
          };
        }
      }
    }
    throw new Error("No image generated.");
  } catch (error: any) {
    throw new Error(error.message || "API Error");
  }
};

export const editGeneratedImage = async (imageDataUri: string, instruction: string): Promise<string> => {
  const base64Data = imageDataUri.replace(/^data:image\/\w+;base64,/, "");
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { inlineData: { mimeType: 'image/png', data: base64Data } },
        { text: `Edit: ${instruction}. Keep eyeglasses and outfit consistent. Negative: looking directly to camera.` }
      ],
    },
  });
  const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  return part ? `data:image/png;base64,${part.inlineData.data}` : imageDataUri;
};

