import React, { useState, useRef } from 'react';
import { ModelForm } from './components/ModelForm';
import { LoadingSpinner } from './components/LoadingSpinner';
import { generateModelWithGlasses, editGeneratedImage } from './services/gemini';
import { ModelAttributes, GenerationState } from './types';

const INITIAL_ATTRIBUTES: ModelAttributes = {
  gender: 'Female',
  age: 'Young Adult (20s)',
  ethnicity: 'South East Asia descent',
  hairStyle: 'Long & Straight',
  hairColor: 'Black',
  clothing: '1 Fashion lay upload (default)',
  environment: 'Reference upload (default)',
  lighting: 'Softbox',
  artStyle: 'Realistic Photo',
  colorGrading: 'Web Use',
  aspectRatio: '3:4',
  skinTexture: 'Realistic (Default)',
  facialExpression: 'Gazing left with slightly smile',
  seed: Math.floor(Math.random() * 10000),
  pose: 'Standing',
  shotType: 'Chest-up/bust shot',
  handProps: 'reference upload (default)'
};

export default function App() {
  const [glassesFile, setGlassesFile] = useState<File | null>(null);
  const [fashionFile, setFashionFile] = useState<File | null>(null);
  const [envRefFile, setEnvRefFile] = useState<File | null>(null);
  const [handPropsFile, setHandPropsFile] = useState<File | null>(null);

  const [glassesPreview, setGlassesPreview] = useState<string | null>(null);
  const [fashionPreview, setFashionPreview] = useState<string | null>(null);
  const [envPreview, setEnvPreview] = useState<string | null>(null);
  const [handPropsPreview, setHandPropsPreview] = useState<string | null>(null);

  const [attributes, setAttributes] = useState<ModelAttributes>(INITIAL_ATTRIBUTES);
  const [state, setState] = useState<GenerationState>({
    isLoading: false,
    results: [],
    error: null,
  });
  const [selectedIdx, setSelectedIdx] = useState<number>(0);

  const handleFileChange = (type: 'glasses' | 'fashion' | 'env' | 'hand', e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const url = URL.createObjectURL(file);
      switch(type) {
        case 'glasses':
          setGlassesFile(file);
          setGlassesPreview(url);
          break;
        case 'fashion':
          setFashionFile(file);
          setFashionPreview(url);
          break;
        case 'env':
          setEnvRefFile(file);
          setEnvPreview(url);
          break;
        case 'hand':
          setHandPropsFile(file);
          setHandPropsPreview(url);
          break;
      }
      setState(prev => ({ ...prev, results: [], error: null }));
    }
  };

  const handleGenerate = async () => {
    if (!glassesFile) {
      setState(prev => ({ ...prev, error: "Upload glasses image." }));
      return;
    }
    setState({ isLoading: true, results: [], error: null });

    try {
      const tasks = [0, 1, 2, 3].map(offset => 
        generateModelWithGlasses(glassesFile, fashionFile, envRefFile, handPropsFile, attributes, attributes.seed + offset)
      );

      const res = await Promise.all(tasks);
      setState({
        isLoading: false,
        results: res.map((r, i) => ({
          imageUrl: r.imageUrl,
          promptJson: r.promptJson,
          seedUsed: attributes.seed + i
        })),
        error: null
      });
      setSelectedIdx(0);
    } catch (err: any) {
      setState({ isLoading: false, results: [], error: err.message });
    }
  };

  const handleDownload = (url: string, seed: number) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `owndays-tryon-${seed}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="min-h-screen bg-white text-black font-sans selection:bg-black selection:text-white">
      {/* Header */}
      <header className="border-b-2 border-black sticky top-0 bg-white z-50">
        <div className="max-w-screen-2xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-black flex items-center justify-center">
              <span className="text-white font-black text-2xl italic">O</span>
            </div>
            <div>
              <h1 className="text-lg font-black tracking-tighter uppercase leading-none">OWNDAYS</h1>
              <p className="text-[10px] font-bold tracking-[0.2em] text-gray-500 uppercase">Eyeglasses AI Try-On</p>
            </div>
          </div>
          <button onClick={() => window.location.reload()} className="text-[10px] font-bold uppercase border-b border-black pb-0.5 hover:opacity-50">Clear Session</button>
        </div>
      </header>

      <main className="max-w-screen-2xl mx-auto px-6 py-10 grid grid-cols-1 lg:grid-cols-12 gap-10">
        {/* Control Sidebar */}
        <div className="lg:col-span-4 space-y-8">
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-2">
              {/* Glasses Upload */}
              <div className="border border-black p-2 relative aspect-square flex flex-col items-center justify-center text-center cursor-pointer hover:bg-gray-50">
                <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileChange('glasses', e)} />
                {glassesPreview ? (
                  <img src={glassesPreview} className="w-full h-full object-contain" alt="Glasses" />
                ) : (
                  <span className="text-[10px] font-bold uppercase">Upload Glasses</span>
                )}
              </div>
              {/* Fashion Upload */}
              <div className="border border-black p-2 relative aspect-square flex flex-col items-center justify-center text-center cursor-pointer hover:bg-gray-50">
                <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileChange('fashion', e)} />
                {fashionPreview ? (
                  <img src={fashionPreview} className="w-full h-full object-contain" alt="Fashion" />
                ) : (
                  <span className="text-[10px] font-bold uppercase">Fashion Lay</span>
                )}
              </div>
              {/* Env Upload */}
              <div className="border border-black p-2 relative aspect-square flex flex-col items-center justify-center text-center cursor-pointer hover:bg-gray-50">
                <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileChange('env', e)} />
                {envPreview ? (
                  <img src={envPreview} className="w-full h-full object-contain" alt="Environment" />
                ) : (
                  <span className="text-[10px] font-bold uppercase">Env Reference</span>
                )}
              </div>
              {/* Hand Upload */}
              <div className="border border-black p-2 relative aspect-square flex flex-col items-center justify-center text-center cursor-pointer hover:bg-gray-50">
                <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileChange('hand', e)} />
                {handPropsPreview ? (
                  <img src={handPropsPreview} className="w-full h-full object-contain" alt="Hand Props" />
                ) : (
                  <span className="text-[10px] font-bold uppercase">Hand Props Ref</span>
                )}
              </div>
            </div>
            <p className="text-[8px] text-gray-400 uppercase font-bold text-center italic">Ref 1: Glasses | Ref 2: Fashion | Ref 3: Env | Ref 4: Hand Props</p>
          </div>

          <ModelForm 
            attributes={attributes} 
            onChange={(k, v) => setAttributes(a => ({...a, [k]: v}))}
            onSubmit={handleGenerate}
            isSubmitting={state.isLoading}
          />

          {state.error && <div className="p-3 bg-black text-white text-[10px] font-bold uppercase">{state.error}</div>}
        </div>

        {/* Results Canvas */}
        <div className="lg:col-span-8 flex flex-col gap-6">
          <div className="min-h-[600px] border border-black p-6 bg-gray-50 relative overflow-hidden">
            {state.isLoading ? (
              <div className="h-full flex items-center justify-center">
                <div className="flex flex-col items-center gap-4">
                  <div className="w-12 h-12 border-4 border-black border-t-transparent rounded-full animate-spin" />
                  <span className="text-[10px] font-black uppercase tracking-widest">Processing Frames...</span>
                </div>
              </div>
            ) : state.results.length > 0 ? (
              <div className="grid grid-cols-2 gap-4 h-full">
                {state.results.map((res, i) => (
                  <div 
                    key={i} 
                    className="flex flex-col gap-2"
                  >
                    <div 
                      onClick={() => setSelectedIdx(i)}
                      className={`relative border-2 bg-white transition-all cursor-pointer aspect-square overflow-hidden ${selectedIdx === i ? 'border-black shadow-[8px_8px_0px_rgba(0,0,0,1)]' : 'border-transparent opacity-50 grayscale hover:grayscale-0 hover:opacity-100'}`}
                    >
                      <img src={res.imageUrl} className="w-full h-full object-cover" />
                      <div className="absolute top-2 left-2 bg-black text-white text-[8px] font-bold px-2 py-0.5 uppercase">Seed: {res.seedUsed}</div>
                    </div>
                    <button 
                      onClick={() => handleDownload(res.imageUrl, res.seedUsed)}
                      className="text-[9px] font-black uppercase tracking-tighter border border-black py-1 hover:bg-black hover:text-white transition-colors"
                    >
                      Download Frame
                    </button>
                  </div>
                ))}
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center opacity-20 text-center">
                <span className="text-8xl mb-4">⊙⊙</span>
                <p className="max-w-xs text-[10px] font-black uppercase leading-tight tracking-widest">Awaiting Technical Input for Virtual Synthesis</p>
              </div>
            )}
          </div>

          {/* Prompt Viewer */}
          {state.results.length > 0 && (
            <div className="border border-black p-4 bg-white">
              <div className="flex justify-between items-center border-b border-black pb-1 mb-3">
                <h4 className="text-[10px] font-black uppercase">Technical Prompt Logic (Variation {selectedIdx + 1})</h4>
                <span className="text-[9px] font-bold">SEED: {state.results[selectedIdx].seedUsed}</span>
              </div>
              <pre className="text-[9px] font-mono overflow-auto max-h-40 bg-gray-50 p-2">
                {state.results[selectedIdx].promptJson}
              </pre>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import { GoogleGenAI } from "@google/genai";
import { ModelAttributes } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Analyzes an environment image and returns a descriptive text prompt.
 */
export const analyzeEnvironment = async (file: File): Promise<string> => {
  try {
    const imgPart = await fileToGenerativePart(file);
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            imgPart,
            { text: "Describe this environment/background in detail for an AI image generation prompt. Focus on the setting, lighting, architectural style, atmosphere, and colors. Return only the descriptive paragraph, no conversational filler." }
          ]
        }
      ]
    });
    return response.text?.trim() || "A realistic environment matching the reference.";
  } catch (error) {
    console.error("Environment analysis failed:", error);
    return "A realistic natural background.";
  }
};

export const generateModelWithGlasses = async (
  glassesFile: File,
  fashionFile: File | null,
  envDescription: string | null,
  handPropsFile: File | null,
  attributes: ModelAttributes,
  specificSeed: number
): Promise<{ imageUrl: string; promptJson: string }> => {
  try {
    const glassesPart = await fileToGenerativePart(glassesFile);
    const parts: any[] = [glassesPart];

    if (fashionFile && attributes.clothing.includes("1")) {
      const fashionPart = await fileToGenerativePart(fashionFile);
      parts.push(fashionPart);
    }

    // Environment image is NOT passed to the final generation. 
    // Instead, we use the analyzed text (envDescription).

    if (handPropsFile && attributes.handProps === "reference upload (default)") {
      const handRefPart = await fileToGenerativePart(handPropsFile);
      parts.push(handRefPart);
    }

    const colorGradingPrompts: Record<string, string> = {
      "Film Simulation": "Analog film aesthetic, subtle grain, natural skin tones, soft shadows.",
      "Magazine": "High-fashion magazine editorial look. Natural contrast, slight saturation, sharp focus, vibrant and clean colors.",
      "Web Use": "E-commerce standard. Middle tone focus with natural color feel, accurate and realistic color representation."
    };

    const environmentPrompts: Record<string, string> = {
      "Reference upload (default)": envDescription || "The environment from the reference.",
      "Clean Spacious Room": "Inside a clean, minimalist white room with soft shadows.",
      "Modern Office": "Sleek contemporary office interior with blurred workstations and architectural glass.",
      "South East Asian Park": "Tropical lush park in Southeast Asia, vibrant greenery and dappled sunlight.",
      "Urban Walking Path (SEA)": "Modern urban pedestrian walkway in a Southeast Asian city, architectural elements in distance.",
      "Midday Coffee Shop": "Stylish coffee shop interior with natural midday light streaming through large windows."
    };

    const isSEAsian = attributes.ethnicity.toLowerCase().includes("south east") || 
                      attributes.ethnicity.toLowerCase().includes("thailand") || 
                      attributes.ethnicity.toLowerCase().includes("singapore") ||
                      attributes.ethnicity.toLowerCase().includes("vietnam");

    const jsonPrompt = {
      subject: `A ${attributes.ethnicity} ${attributes.gender} model, age ${attributes.age}.`,
      eyewear: "Model is wearing the exact eyeglasses shown in the primary reference image.",
      clothing: (fashionFile && attributes.clothing.includes("1"))
        ? "Model is wearing the outfit shown in the fashion flat-lay reference image." 
        : attributes.clothing,
      features: isSEAsian ? "Authentic Southeast Asian facial features, distinct eye shape." : "Natural features.",
      skin: attributes.skinTexture,
      expression: attributes.facialExpression,
      environment: environmentPrompts[attributes.environment] || attributes.environment,
      hand_props: (handPropsFile && attributes.handProps.includes("reference"))
        ? "Model is holding the item shown in the hand props reference image."
        : `Model is holding a ${attributes.handProps}.`,
      composition: {
        pose: `The model is ${attributes.pose}.`,
        shot_type: attributes.shotType,
      },
      photography: {
        style: attributes.artStyle,
        lighting: attributes.lighting,
        color_grading: colorGradingPrompts[attributes.colorGrading] || attributes.colorGrading,
        skin_detail: attributes.skinTexture,
        negative_aspect: "looking directly to camera"
      }
    };

    const textPrompt = `
      Create a photorealistic portrait.
      1. Model MUST wear the eyeglasses from the first image.
      ${fashionFile ? "2. Model wears the outfit from the clothing reference image." : ""}
      3. Environment details: ${jsonPrompt.environment}
      ${handPropsFile ? "4. Model is holding the prop from the hand props reference image." : ""}
      5. Style guidelines: ${JSON.stringify(jsonPrompt)}
      NEGATIVE: looking directly to camera, western features, caucasian, european face.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [...parts, { text: textPrompt }] },
      config: {
        imageConfig: { 
          aspectRatio: attributes.aspectRatio,
          seed: specificSeed
        }
      }
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return { 
            imageUrl: `data:image/png;base64,${part.inlineData.data}`,
            promptJson: JSON.stringify(jsonPrompt, null, 2)
          };
        }
      }
    }
    throw new Error("No image generated.");
  } catch (error: any) {
    throw new Error(error.message || "API Error");
  }
};

export const editGeneratedImage = async (imageDataUri: string, instruction: string): Promise<string> => {
  const base64Data = imageDataUri.replace(/^data:image\/\w+;base64,/, "");
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { inlineData: { mimeType: 'image/png', data: base64Data } },
        { text: `Edit: ${instruction}. Keep eyeglasses and outfit consistent. Negative: looking directly to camera.` }
      ],
    },
  });
  const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  return part ? `data:image/png;base64,${part.inlineData.data}` : imageDataUri;
};

